# ============================================================================
# Per-specimen pathway overrepresentation
# ============================================================================

from pathlib import Path
import traceback
import numpy as np
import pandas as pd
from scipy.stats import hypergeom


ROOT = PROJECT_ROOT
INPUT = ROOT / "Results" / "Stage5A"
OUT = ROOT / "Results" / "Stage5B"
CACHE = ROOT / "resources" / "gene_sets"
OUT.mkdir(parents=True, exist_ok=True)
SAMPLES = ["1142243F", "1160920F", "CID4290", "CID4465", "CID44971", "CID4535"]
LIBRARIES = ["GO_Biological_Process_2025", "Reactome_2022"]
TOP_N = 80
MIN_BACKGROUND_GENES = 5
MAX_BACKGROUND_GENES = 400
MIN_HITS = 3
FDR = 0.05
report, errors, records, stats = [], [], [], []


def log(s=""):
    report.append(str(s))


def bh(p):
    p = np.asarray(p, dtype=float)
    order = np.argsort(p)
    adjusted = np.empty(len(p), dtype=float)
    adjusted[order] = np.minimum(
        1,
        np.minimum.accumulate((p[order] * len(p) / np.arange(1, len(p) + 1))[::-1])[
            ::-1
        ],
    )
    return adjusted


def fetch_gmt(library):
    destination = CACHE / (library + ".gmt")
    if not destination.exists() or destination.stat().st_size == 0:
        raise FileNotFoundError(
            f"Missing pinned pathway snapshot: {destination}. "
            "Do not substitute a newer online library without scientific approval."
        )
    pathways = {}
    for line in destination.read_text(
        encoding="utf-8-sig", errors="replace"
    ).splitlines():
        cols = line.rstrip("\n").split("\t")
        if len(cols) < 3:
            continue
        name = cols[0].strip()
        # Enrichr GMT: term, optional description, genes... ; discard blanks.
        genes = {x.strip().upper() for x in cols[2:] if x.strip()}
        if name and genes:
            pathways[name] = genes
    if len(pathways) < 50:
        raise RuntimeError(
            f"{library} GMT has only {len(pathways)} usable pathways; "
            f"delete {destination} and rerun if file was malformed."
        )
    log(
        f"{library}: {len(pathways):,} reference pathways loaded; cached at {destination}"
    )
    return pathways


def enrich(sample, library, pathways, data):
    universe = set(data["gene_symbol"].str.upper())
    selected = set(data.nlargest(TOP_N, "moran_I")["gene_symbol"].str.upper())
    if len(universe) != 800 or len(selected) != TOP_N:
        raise ValueError(
            f"{sample}: expected 800 unique tested and {TOP_N} unique selected genes"
        )
    results = []
    for name, source_genes in pathways.items():
        pathway = source_genes & universe
        K = len(pathway)
        if not (MIN_BACKGROUND_GENES <= K <= MAX_BACKGROUND_GENES):
            continue
        overlap = selected & pathway
        k = len(overlap)
        # Test ALL eligible pathways, including zero-hit ones, to retain
        # the complete FDR testing family. MIN_HITS is a display filter only.
        p = float(hypergeom.sf(k - 1, len(universe), K, TOP_N)) if k else 1.0
        expected = TOP_N * K / len(universe)
        results.append(
            {
                "sample": sample,
                "library": library,
                "pathway": name,
                "background_size": len(universe),
                "top_spatial_genes": TOP_N,
                "pathway_genes_in_background": K,
                "overlap_count": k,
                "expected_overlap": expected,
                "fold_enrichment": (k / expected if expected else np.nan),
                "p_value": p,
                "overlap_genes": ";".join(sorted(overlap)),
            }
        )
    if not results:
        raise RuntimeError(
            f"{sample} {library}: no pathways passed universe size criteria"
        )
    tab = pd.DataFrame(results)
    tab["BH_FDR"] = bh(tab["p_value"])
    tab["significant"] = (tab["BH_FDR"] < FDR) & (tab["overlap_count"] >= MIN_HITS)
    tab = tab.sort_values(["BH_FDR", "fold_enrichment", "pathway"])
    safe = "GO_BP" if "GO_" in library else "Reactome"
    tab.to_csv(OUT / f"{sample}_{safe}_enrichment_all_tested.csv", index=False)
    sig = tab[tab["significant"]].copy()
    stats.append(
        {
            "sample": sample,
            "library": library,
            "tested_pathways": len(tab),
            "FDR_significant_min3hits": len(sig),
            "best_q": float(tab["BH_FDR"].min()),
        }
    )
    log(
        f"{sample} | {library}: {len(tab):,} pathways tested; "
        f"{len(sig)} significant (BH q<0.05, >=3 genes)"
    )
    for row in sig.head(5).itertuples():
        log(
            f"  {row.pathway} | q={row.BH_FDR:.3g} | hits={row.overlap_count} "
            f"| enrichment={row.fold_enrichment:.2f}x | {row.overlap_genes[:125]}"
        )
    if len(sig):
        records.extend(sig.to_dict("records"))


log("PROJECT 2 | STAGE 5B — EXPLORATORY SPATIAL GENE PATHWAY ENRICHMENT")
log("Selection: top 80 of each specimen's 800 Stage5A-tested genes, ranked by Moran I.")
log("Background: the SAME 800 tested genes for that specimen, NOT the entire genome.")
log(
    "Test: one-sided hypergeometric overrepresentation; BH across ALL eligible pathways per library/specimen."
)
log(
    "Interpretation: enrichment of top spatial genes, NOT pathway activity or independent patient replication."
)
log(
    "Stage5A >94% significant genes: using all FDR hits would make enrichment uninformative."
)

try:
    library_sets = {library: fetch_gmt(library) for library in LIBRARIES}
except Exception as exc:
    log("PATHWAY DOWNLOAD ERROR: " + str(exc))
    log(traceback.format_exc())
    (OUT / "Stage5B_Results.txt").write_text("\n".join(report), encoding="utf-8")
    print("\n".join(report))
    raise

for sample in SAMPLES:
    try:
        filename = INPUT / f"{sample}_MoranI_gene_results.csv"
        if not filename.exists():
            raise FileNotFoundError(filename)
        df = pd.read_csv(filename)
        required = {"gene_symbol", "moran_I", "BH_FDR"}
        if not required.issubset(df.columns):
            raise ValueError(f"Missing columns {required - set(df.columns)}")
        if (
            len(df) != 800
            or df["gene_symbol"].isna().any()
            or df["gene_symbol"].str.upper().duplicated().any()
        ):
            raise ValueError(
                "Stage5A file must contain 800 unique nonmissing gene symbols"
            )
        if not np.isfinite(pd.to_numeric(df["moran_I"], errors="coerce")).all():
            raise ValueError("Missing or invalid Moran I values")
        df["gene_symbol"] = df["gene_symbol"].astype(str).str.upper()
        df["moran_I"] = pd.to_numeric(df["moran_I"])
        (
            df.nlargest(TOP_N, "moran_I")[["gene_symbol", "moran_I", "BH_FDR"]].to_csv(
                OUT / f"{sample}_top80_spatial_genes.csv", index=False
            )
        )
        for library, pathways in library_sets.items():
            enrich(sample, library, pathways, df)
    except Exception as exc:
        errors.append(f"{sample}: {type(exc).__name__}: {exc}")
        log("ERROR: " + errors[-1])
        log(traceback.format_exc())

log("\n" + "=" * 95)
log("FINAL ANALYSIS SUMMARY")
log("=" * 95)
if stats:
    overview = pd.DataFrame(stats)
    overview.to_csv(OUT / "Stage5B_summary.csv", index=False)
    log("\nPER-SPECIMEN ENRICHMENT SUMMARY\n" + overview.to_string(index=False))
if records:
    enriched = pd.DataFrame(records)
    enriched.to_csv(OUT / "Stage5B_significant_enrichments.csv", index=False)
    # A recurring pathway must be significant independently in >=2 specimens.
    recurrence = (
        enriched.groupby(["library", "pathway"])
        .agg(
            specimens=("sample", "nunique"),
            median_fold=("fold_enrichment", "median"),
            max_q=("BH_FDR", "max"),
            specimens_list=("sample", lambda x: ";".join(sorted(set(x)))),
        )
        .reset_index()
        .sort_values(["specimens", "median_fold"], ascending=[False, False])
    )
    recurrence.to_csv(OUT / "Stage5B_recurrent_pathways.csv", index=False)
    log("\nTOP RECURRENT ENRICHED PATHWAYS (per-specimen BH FDR <0.05)")
    log(recurrence.head(25).to_string(index=False))
    log(f"Pathways enriched in >=2 specimens: {int((recurrence.specimens >= 2).sum())}")
else:
    log(
        "\nNo pathways survived BH FDR and minimum 3-overlap filter. This is a valid result."
    )
log(f"Completed analysis pairs: {len(stats)}/12")
log(
    "CAUTION: pathway databases overlap heavily; significance is conditional on variance-selected universe."
)
log(
    "CAUTION: Stage5A genes are spatially correlated and high-ranked genes may reflect histology or depth."
)
log(
    "CAUTION: no sample-level inferential meta-analysis (only six tumours; 4 TNBC and 2 ER)."
)
log(f"Outputs: {OUT}")
if errors:
    log("ERRORS:\n" + "\n".join(errors))
(OUT / "Stage5B_Results.txt").write_text("\n".join(report), encoding="utf-8")
print("\n".join(report))
if errors or len(stats) != len(SAMPLES) * len(LIBRARIES):
    raise RuntimeError(
        f"Stage 5B incomplete: {len(stats)}/12 analyses completed; consult Stage5B_Results.txt"
    )

# ============================================================================
# Cross-tumour descriptive integration
# ============================================================================

from pathlib import Path
import traceback
import numpy as np
import pandas as pd


ROOT = PROJECT_ROOT
BASE = ROOT / "Results"
OUT = BASE / "Stage6A"
OUT.mkdir(parents=True, exist_ok=True)
SAMPLES = ["1142243F", "1160920F", "CID4290", "CID4465", "CID44971", "CID4535"]
SUBTYPE = {s: ("ER" if s in ("CID4290", "CID4535") else "TNBC") for s in SAMPLES}
lines = []


def log(s=""):
    lines.append(str(s))


def read(stage, name, required):
    p = BASE / stage / name
    if not p.is_file():
        raise FileNotFoundError(f"Missing prerequisite: {p}")
    df = pd.read_csv(p)
    missing = set(required) - set(df.columns)
    if missing:
        raise ValueError(f"{p.name}: missing columns {sorted(missing)}")
    return df


log("PROJECT 2 | STAGE 6A — CROSS-TUMOUR INTEGRATION")
log(
    "Descriptive integration of existing, independently saved results; no new statistical tests."
)
log("Tumours (n=6), not spots, are independent specimens. No subtype hypothesis tests.")
try:
    spot_counts = []
    for s in SAMPLES:
        df = read("Stage1D", f"{s}_spot_metadata.csv", ["barcode"])
        spot_counts.append({"sample": s, "subtype": SUBTYPE[s], "spots": len(df)})
    pd.DataFrame(spot_counts).to_csv(OUT / "Stage6A_sample_overview.csv", index=False)

    pro = read(
        "Stage3B",
        "Stage3B_programme_summary.csv",
        ["sample", "programme", "spatial_neighbour_r", "spearman_depth", "genes_used"],
    )
    pro = pro[pro["sample"].isin(SAMPLES)].copy()
    if (
        pro.groupby("sample")["programme"].nunique().min() < 6
        or pro["sample"].nunique() != 6
    ):
        raise ValueError("Incomplete Stage3B programme coverage")
    pro["subtype"] = pro["sample"].map(SUBTYPE)
    pro["abs_depth_r"] = pd.to_numeric(pro["spearman_depth"]).abs()
    pro.to_csv(OUT / "Stage6A_all_programme_metrics.csv", index=False)
    programme_summary = (
        pro.groupby("programme")
        .agg(
            tumours=("sample", "nunique"),
            median_spatial_r=("spatial_neighbour_r", "median"),
            min_spatial_r=("spatial_neighbour_r", "min"),
            max_spatial_r=("spatial_neighbour_r", "max"),
            max_abs_depth_r=("abs_depth_r", "max"),
            n_depth_abs_r_ge_0_4=("abs_depth_r", lambda x: int((x >= 0.4).sum())),
        )
        .reset_index()
        .sort_values("median_spatial_r", ascending=False)
    )
    programme_summary.to_csv(OUT / "Stage6A_programme_recurrence.csv", index=False)
    subtype_summary = (
        pro.groupby(["programme", "subtype"])
        .agg(
            n_tumours=("sample", "nunique"),
            median_spatial_r=("spatial_neighbour_r", "median"),
            median_depth_r=("spearman_depth", "median"),
        )
        .reset_index()
    )
    subtype_summary.to_csv(OUT / "Stage6A_subtype_descriptive.csv", index=False)

    moran = read(
        "Stage5A",
        "Stage5A_recurrent_spatial_genes.csv",
        ["gene_symbol", "specimens", "median_I", "max_abs_depth_r"],
    )
    moran = moran.sort_values(["specimens", "median_I"], ascending=[False, False])
    moran.to_csv(OUT / "Stage6A_recurrent_spatial_genes.csv", index=False)
    conservative = moran[(moran["specimens"] == 6) & (moran["max_abs_depth_r"] < 0.4)]
    conservative.to_csv(
        OUT / "Stage6A_candidate_recurrent_genes_depth_screen.csv", index=False
    )

    pathways = read(
        "Stage5B",
        "Stage5B_significant_enrichments.csv",
        ["sample", "library", "pathway", "BH_FDR", "fold_enrichment", "overlap_genes"],
    )
    pathways["subtype"] = pathways["sample"].map(SUBTYPE)
    if pathways["subtype"].isna().any():
        raise ValueError("Unexpected specimen in Stage5B pathways")
    recurrence = (
        pathways.groupby(["library", "pathway"])
        .agg(
            n_tumours=("sample", "nunique"),
            median_fold=("fold_enrichment", "median"),
            max_q=("BH_FDR", "max"),
            samples=("sample", lambda a: ";".join(sorted(set(a)))),
        )
        .reset_index()
        .sort_values(["n_tumours", "median_fold"], ascending=[False, False])
    )
    recurrence.to_csv(OUT / "Stage6A_recurrent_enriched_pathways.csv", index=False)

    # These transparent keyword categories are merely reporting aids. Pathway labels
    # overlap and some share the same underlying genes; this is not ontology analysis.
    themes = {
        "Immune / antigen presentation / interferon": [
            "immune",
            "antigen",
            "interferon",
            "complement",
            "antibody",
            "t cell",
            "humoral",
        ],
        "Extracellular matrix / collagen / stromal": [
            "extracellular matrix",
            "collagen",
            "scavenger receptor",
        ],
        "Translation / ribosome / RNA processing": [
            "translation",
            "ribosom",
            "peptide chain",
            "selenocysteine",
            "selenoamino",
            "rrna",
            "rna processing",
            "nonsense mediated",
            "40s subunit",
            "amino acid deficiency",
        ],
        "Epithelial / keratinization": ["keratinization"],
    }
    theme_rows = []
    for theme, terms in themes.items():
        included = pathways[
            pathways["pathway"]
            .astype(str)
            .str.lower()
            .apply(lambda s: any(term in s for term in terms))
        ]
        theme_rows.append(
            {
                "theme": theme,
                "tumours_with_any_enrichment": included["sample"].nunique(),
                "samples": ";".join(sorted(included["sample"].unique())),
                "significant_pathway_sample_rows": len(included),
                "unique_library_pathway_terms": len(
                    included[["library", "pathway"]].drop_duplicates()
                ),
            }
        )
    pd.DataFrame(theme_rows).to_csv(
        OUT / "Stage6A_pathway_themes_descriptive.csv", index=False
    )

    log("\nSAMPLE INVENTORY")
    log(pd.DataFrame(spot_counts).to_string(index=False))
    log("\nSPATIAL PROGRAMMES — RECURRING LOCAL SIMILARITY (NOT p-VALUES)")
    log(programme_summary.round(3).to_string(index=False))
    log(
        "\nSPATIAL PROGRAMMES — SUBTYPE DESCRIPTIVES (4 TNBC, 2 ER; no significance tests)"
    )
    log(subtype_summary.round(3).to_string(index=False))
    log("\nSPATIALLY STRUCTURED GENES IN ALL SIX SAMPLES")
    log(
        f"n={int((moran['specimens'] == 6).sum())}; after descriptive |depth r| < 0.4 screen in every tumour n={len(conservative)}"
    )
    log(
        conservative.head(20).round(3).to_string(index=False)
        if len(conservative)
        else "None"
    )
    log("\nIDENTICAL ENRICHED PATHWAYS RECURRING IN >=2 SAMPLES")
    multi = recurrence[recurrence.n_tumours >= 2]
    log(multi.head(30).round(4).to_string(index=False) if len(multi) else "None")
    log(
        f"Identical recurring pathways: {len(multi)}; >=3 tumours: {int((recurrence.n_tumours >= 3).sum())}"
    )
    log("\nBROAD BIOLOGICAL THEMES (overlapping labels; descriptive only)")
    log(pd.DataFrame(theme_rows).to_string(index=False))
    log("\nSCIENTIFIC INTERPRETATION")
    log(
        "Spatial signature similarity reflects local structure, NOT measured cell counts or cell identities."
    )
    log(
        "Enrichment means pathway-member genes are overrepresented among TOP 80 Moran-I genes versus the 800 tested genes, within each tumour."
    )
    log(
        "It does NOT mean entire pathways are spatially active or up/downregulated. Gene selection and overlapping gene sets matter."
    )
    log(
        "Depth screening is descriptive; low depth correlation does NOT eliminate confounding."
    )
    log("Do not infer subtype differences with n=4 TNBC and n=2 ER specimens.")
    log(
        "Focused findings from Stages 4A–4C remain SINGLE-TUMOUR or THREE-TUMOUR descriptive analyses, not replicated clinical effects."
    )
    log(
        "NEXT: examine images/histological overlays and select a few coherent recurrent programmes for final figures and robustness checks."
    )
    log(f"OUTPUTS: {OUT}")
except Exception as ex:
    log("\nERROR: " + f"{type(ex).__name__}: {ex}")
    log(traceback.format_exc())
    raise
finally:
    msg = "\n".join(lines)
    (OUT / "Stage6A_Consolidated_Results.txt").write_text(msg, encoding="utf-8")
    print(
        "\n" + "=" * 80 + "\nFINAL ANALYSIS SUMMARY\n" + "=" * 80
    )
    print(msg)
